import time

api_pages = [
    {"results": [{"id": 1, "name": "Alice Johnson", "role": "Engineer"}], "next_page": 2},
    {"results": [{"id": 2, "name": "Bob Smith", "role": "Designer"}], "next_page": None},
]

def fetch_page(page_number):
    return api_pages[page_number - 1]

def record_to_text(record):
    return f"{record['name']} works as a {record['role']}."

all_documents = []
page_number = 1
while page_number is not None:
    page = fetch_page(page_number)
    for record in page["results"]:
        all_documents.append(record_to_text(record))
    page_number = page["next_page"]
    time.sleep(0.1)  # pace requests to respect the API's rate limit

print("Documents assembled across all pages:\n")
for doc in all_documents:
    print(f"  '{doc}'")
